\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}
\usepackage{scrextend}
\pgfplotsset{compat=newest}

\begin{document}

\pagestyle{empty}

\begin{tikzpicture}

\begin{axis}[
trig format plots=rad,
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
legend style={font=\footnotesize},
tick style={line width=0.8pt, color=black},
axis line style = thick,
axis y line = center,
axis x line = middle,
xlabel = $x$,
ylabel = {$y$},
xmin = -4,
xmax = 6,
ymin = -9,
ymax = 3,
xtick = {-2,-1,5},
ytick = {-2},
xticklabels = {$-2$,$-1$,$5$},
yticklabels = {$-2$},
%% Here, we can control the positioning of each individual tick.
x tick label style={xshift={(\tick==-2)*0pt}},
x tick label style={xshift={(\tick==-1)*-2pt}},
x tick label style={xshift={(\tick==5)*3pt}},
y tick label style={yshift={(\tick==-2)*0pt}},
every axis x label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=west,
},
every axis y label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=south,
}
]

% Graphic
\addplot [domain=-10:10,samples=200,color=red,line width=1pt]{(1/5)*(x+1)*(x+2)*(x-5)};



\end{axis}

\end{tikzpicture}
\end{document}

